import os
import sys
import hashlib
import argparse
from collections import defaultdict

def get_sha256_hash(filepath, chunk_size=8192):
    """Calculate the SHA-256 hash of a file."""
    hasher = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(chunk_size):
                hasher.update(chunk)
        return hasher.hexdigest()
    except OSError as e:
        print(f"Error reading {filepath}: {e}", file=sys.stderr)
        return None

def find_duplicate_files(root_dir):
    """Find and group duplicate files in a directory recursively."""
    # Step 1: Group files by size first (optimization to avoid hashing unique files)
    files_by_size = defaultdict(list)

    for dirpath, _, filenames in os.walk(root_dir):
        for filename in filenames:
            filepath = os.path.join(dirpath, filename)
            try:
                # Skip symlinks to avoid counting them as duplicate files or entering infinite loops
                if not os.path.islink(filepath):
                    size = os.path.getsize(filepath)
                    files_by_size[size].append(filepath)
            except OSError as e:
                print(f"Error accessing {filepath}: {e}", file=sys.stderr)

    # Step 2: Calculate hashes only for files that share a file size
    files_by_hash = defaultdict(list)

    for size, filepaths in files_by_size.items():
        if len(filepaths) > 1:
            for filepath in filepaths:
                file_hash = get_sha256_hash(filepath)
                if file_hash is not None:
                    files_by_hash[file_hash].append(filepath)

    # Step 3: Filter out hashes that only have one file associated with them
    duplicates = {h: paths for h, paths in files_by_hash.items() if len(paths) > 1}

    return duplicates

def main():
    parser = argparse.ArgumentParser(description="Recursively find duplicate files based on SHA-256 hash.")
    parser.add_argument("directory", help="The directory path to scan for duplicates.")
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"Error: '{args.directory}' is not a valid directory.", file=sys.stderr)
        sys.exit(1)

    print(f"Scanning '{args.directory}' for duplicates...")
    duplicates = find_duplicate_files(args.directory)

    if not duplicates:
        print("No duplicate files found.")
        return

    print(f"\nFound {len(duplicates)} sets of duplicate files:\n")
    for file_hash, filepaths in duplicates.items():
        print(f"SHA-256: {file_hash}")
        for filepath in filepaths:
            print(f"  - {filepath}")
        print()

if __name__ == "__main__":
    main()
```

### Usage
Save the script to a file (e.g., `find_duplicates.py`) and run it from the terminal, passing the target directory as an argument:

```bash
python find_duplicates.py /path/to/directory
```

### Key Features of this Implementation:
* **Memory Efficient Hashing**: Reads files in 8KB chunks so it can handle multi-gigabyte files without exhausting system RAM.
* **Pre-Optimization by Size**: Grouping files by size first (`os.path.getsize`) ensures the script only performs the expensive SHA-256 hashing operation on files that have a high probability of being duplicates.
* **Symlink & Permission Handling**: Safely ignores symlinks to prevent infinite loops and catches `OSError` to prevent the script from crashing when it encounters protected system files.
